<?php
declare(strict_types=1);
if(!defined('CWP_BOOT')){http_response_code(404);exit;}
require_once CWP_CODE_ROOT.'/app/providers/domain_expiry.php';
function domain_expiry_render(array $p):void {
    $labels=['not_observed'=>'No expiry timestamp has been saved for this assignment.','assignment_changed'=>'The studio needs to refresh the expiry observation for this assignment.','observed'=>'Latest saved observation','stale'=>'The saved observation is older than 15 minutes. Ask the studio to refresh it.','unfinished'=>'The latest expiry refresh has not completed.','unavailable'=>'The latest expiry timestamp is unavailable.','access_changed'=>'The assignment or account changed during the latest refresh.','credential'=>'The studio needs to review the account connection.','refused'=>'The latest expiry refresh could not be completed.'];
    echo '<div data-domain-expiry style="overflow-wrap:anywhere"><h3 style="overflow-wrap:anywhere">'.esc($p['domain']??'Registered domain').'</h3><p>'.esc($labels[$p['status']]??'The saved expiry observation needs review.').'</p>';
    if($p['timestamp']!==null)echo '<p><strong>Provider expiry timestamp: '.esc($p['timestamp']).'</strong><br><span class="hint">Observed '.esc(gmdate('Y-m-d H:i:s',$p['observed_epoch'])).' UTC</span></p>';
    echo '<p class="hint">This saved timestamp does not confirm current domain status, a price, or a completed renewal.</p>';
    if($p['history']){echo '<details><summary>Saved observation history</summary><ul>';foreach($p['history'] as $r)echo '<li>'.esc(gmdate('Y-m-d H:i:s',$r['observed_epoch'])).' UTC — '.($r['timestamp']!==null?'Observed expiry timestamp '.esc($r['timestamp']):esc($r['state']==='unfinished'?'Refresh unfinished':'Expiry timestamp unavailable')).'</li>';echo '</ul></details>';}
    echo '</div>';
}
function domain_expiry_admin_render():void {
    provider_settings_manager();echo '<section class="workspace-card" id="domain-expiry"><h2>Domain expiry observations</h2><p>Save the provider expiry timestamp for an assigned registered domain. Clients see saved observations; renewal dates and renewal review remain separate.</p>';
    try{$ready=provider_inventory_ready()&&provider_registrar_ready()&&domain_expiry_ready();}catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p></section>';return;}
    if(!$ready){echo '<form method="post">';admin_action('provider_inventory_expiry_prepare');admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn gold">Enable expiry timestamps</button></form><p class="hint">Prepare registered domains above first.</p></section>';return;}
    $page=max(1,min(10000,(int)($_GET['expiry_page']??1)));$links=all('SELECT l.id,l.revision,c.name AS client_name FROM '.table('provider_registrar_links').' l JOIN '.table('studio_clients').' c ON c.id=l.client_id ORDER BY l.domain LIMIT 20 OFFSET '.(($page-1)*20));if(!$links)echo '<p>Assign a registered domain to a client first.</p>';
    foreach($links as $l){echo '<article class="workspace-card"><p>'.esc($l['client_name']).'</p>';try{[$b,$p]=staff_locked(fn()=>staff_transaction(fn()=>[domain_expiry_binding($l['id'],(int)$l['revision']),domain_expiry_project($l['id'],(int)$l['revision'])]));domain_expiry_render($p);echo '<form method="post">';admin_action('provider_inventory_expiry_refresh');foreach(['link_id'=>$l['id'],'link_revision'=>$l['revision'],'profile_revision'=>$b->registrar->data['profile_revision'],'refresh_id'=>$b->registrar->data['source_refresh_id']] as $k=>$v)echo '<input type="hidden" name="'.esc($k).'" value="'.esc((string)$v).'">';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn outline">Refresh expiry timestamp</button></form>';}
        catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p>';}echo '</article>';}
    echo '<nav class="button-row" aria-label="Expiry observation pages">';if($page>1)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['expiry_page'=>$page-1])).'#domain-expiry">Previous domains</a>';if(count($links)===20&&$page<10000)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['expiry_page'=>$page+1])).'#domain-expiry">More domains</a>';echo '</nav></section>';
}
